mapper.select:
SELECT DISTINCT p.performance_id, p.employee_id, p.work_item, p.title, p.start_date, p.end_date, p.status, p.achievement_rate, p.`comment` FROM performance p INNER JOIN evaluation e ON e.employee_id = p.employee_id AND e.approval_id = #{employeeId}
p.employee_id = #{appraiseeId}
AND
p.status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
ORDER BY p.created_at DESC
